"""Read and write asset specs in MegaMek's .bfs format, extended with
provenance fields (provenance, approvedBy, approvedOn, history, notes)."""

from __future__ import annotations

import uuid as _uuid
from datetime import date

import yaml

from .megamek import Unit

HEADER = """\
# Generated by BSP Card Generator (unofficial fan tool).
# Derived from MegaMek Data (C) The MegaMek Team, licensed under
# CC BY-NC-SA 4.0: https://creativecommons.org/licenses/by-nc-sa/4.0/
# BattleTech is a trademark of The Topps Company, Inc. Not an official card.
"""

MODE = {"t": "TRACKED", "w": "WHEELED", "h": "HOVER", "v": "VTOL",
        "g": "WIGE", "n": "NAVAL"}
ASSET_TYPE = {"Tank": "Vehicle", "VTOL": "Vehicle", "SupportTank": "Vehicle",
              "SupportVTOL": "Vehicle", "Infantry": "ConvInfantry",
              "BattleArmor": "BattleArmor", "GunEmplacement": "Emplacement"}


def to_bfs(unit: Unit, spec, cost: dict, skill: int,
           provenance: str = "auto", notes: list[str] | None = None) -> dict:
    """Build a .bfs record (as a dict) for a derived spec."""
    rng = list(spec.range) if spec.range else [-1, -1, -1]
    dmg = spec.damage or (0, 0)
    rec = {
        "uuid": str(_uuid.uuid5(_uuid.NAMESPACE_URL, f"bsp-card-generator/{unit.uuid}")),
        "linkedUnitId": unit.uuid,
        "chassis": unit.name,
        "model": unit.model,
        "assetType": ASSET_TYPE.get(unit.unit_type, "Vehicle"),
        "techBase": "Clan" if unit.clan else "IS",
        "movement": {"mp": spec.mp, "mode": MODE.get(spec.mode, spec.mode.upper())},
        "tmm": spec.tmm,
        "range": rng,
        "skill": {"standard": skill, "veteran": skill - 1},
        "damage": {"perHit": int(dmg[0]), "hits": int(dmg[1])},
        "destroyCheck": spec.check,
        "threshold": spec.threshold,
        "cost": {"standard": cost["regular"], "veteran": cost["veteran"]},
        "specials": sorted(set(spec.specials)) or [],
        # --- BSP Card Generator extensions ---
        "provenance": provenance,           # official | approved | auto
        "approvedBy": None,
        "approvedOn": None,
        "generatedOn": date.today().isoformat(),
        "notes": (notes or []) + list(spec.notes),
    }
    if unit.mul_id:
        rec["mulId"] = unit.mul_id
    return rec


def dumps(rec: dict) -> str:
    return HEADER + "\n" + yaml.safe_dump(rec, sort_keys=False, allow_unicode=True)


def load(path) -> dict:
    with open(path, encoding="utf-8") as f:
        return yaml.safe_load(f)
